36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "registration_date", columnDefinition = "DATE")
56	    private LocalDate registrationDate;
57	
58	    @Column(name = "customer_code")
59	    private String customerCode;
60	
61	    @Column(name = "household_id")
62	    private String householdId;
63	
64	    @Column(name = "namesake_count")
65	    private Integer namesakeCount;
66	
67	    @Column(name = "bulk_signup_warning")
68	    private boolean bulkSignupWarning;
69	
70	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
71	    private Set<Pet> pets;
72	
73	    public String getAddress() {
74	        return this.address;
75	    }
76	
77	    public void setAddress(String address) {
78	        this.address = address;
79	    }
80	
81	    public String getCity() {
82	        return this.city;
83	    }
84	
85	    public void setCity(String city) {
86	        this.city = city;
87	    }
88	
89	    public String getTelephone() {
90	        return this.telephone;
91	    }
92	
93	    public void setTelephone(String telephone) {
94	        this.telephone = telephone;
95	    }
96	
97	    public String getEmail() {
98	        return this.email;
99	    }
100	
101	    /**
102	     * Stores the email in its canonical lower-cased form so it is always persisted and
103	     * returned lower-cased, regardless of the casing supplied by the client.
104	     */
105	    public void setEmail(String email) {
106	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
107	    }
108	
109	    public LocalDate getRegistrationDate() {
110	        return this.registrationDate;
111	    }
112	
113	    public void setRegistrationDate(LocalDate registrationDate) {
114	        this.registrationDate = registrationDate;
115	    }
116	
117	    public String getCustomerCode() {
118	        return this.customerCode;
119	    }
120	
121	    public void setCustomerCode(String customerCode) {
122	        this.customerCode = customerCode;
123	    }
124	
125	    public String getHouseholdId() {
126	        return this.householdId;
127	    }
128	
129	    public void setHouseholdId(String householdId) {
130	        this.householdId = householdId;
131	    }
132	
133	    public Integer getNamesakeCount() {
134	        return this.namesakeCount;
135	    }
136	
137	    public void setNamesakeCount(Integer namesakeCount) {
138	        this.namesakeCount = namesakeCount;
139	    }
140	
141	    public boolean isBulkSignupWarning() {
142	        return this.bulkSignupWarning;
143	    }
144	
145	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
146	        this.bulkSignupWarning = bulkSignupWarning;
147	    }
148	
149	    /**
150	     * On first persist, default the registration date to the server's current date when the
151	     * client did not supply one, then roll the effective date forward so it always falls on a
152	     * business day (a weekend moves to the following Monday).
153	     */
154	    @PrePersist
155	    private void defaultRegistrationDate() {
156	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
157	        this.registrationDate = BusinessDay.rollForward(effectiveDate);
158	    }
159	
160	    protected Set<Pet> getPetsInternal() {
161	        if (this.pets == null) {
162	            this.pets = new HashSet<>();
163	        }
164	        return this.pets;
165	    }
166	
167	    protected void setPetsInternal(Set<Pet> pets) {
168	        this.pets = pets;
169	    }
170	
171	    public List<Pet> getPets() {
172	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
173	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
174	        return Collections.unmodifiableList(sortedPets);
175	    }
176	
177	    public void setPets(List<Pet> pets) {
178	        this.pets = new HashSet<>(pets);
179	    }
180	
181	    public void addPet(Pet pet) {
182	        getPetsInternal().add(pet);
183	        pet.setOwner(this);
184	    }
185	
186	    /**
187	     * Return the Pet with the given name, or null if none found for this Owner.
188	     *
189	     * @param name to test
190	     * @return true if pet name is already in use
191	     */
192	    public Pet getPet(String name) {
193	        return getPet(name, false);
194	    }
195	
196	    /**
197	     * Return the Pet with the given name, or null if none found for this Owner.
198	     *
199	     * @param name to test
200	     * @return true if pet name is already in use
201	     */
202	    public Pet getPet(String name, boolean ignoreNew) {
203	        name = name.toLowerCase();
204	        for (Pet pet : getPetsInternal()) {
205	            if (!ignoreNew || !pet.isNew()) {
206	                String compName = pet.getName();
207	                compName = compName.toLowerCase();
208	                if (compName.equals(name)) {
209	                    return pet;
210	                }
211	            }
212	        }
213	        return null;
214	    }
215	
216	    public Pet getPet(Integer petId) {
217	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
218	    }
219	
220	    @Override
221	    public String toString() {
222	        return new ToStringCreator(this)
223	
224	            .append("id", this.getId())
225	            .append("new", this.isNew())
226	            .append("lastName", this.getLastName())
227	            .append("firstName", this.getFirstName())
228	            .append("address", this.address)
229	            .append("city", this.city)
230	            .append("telephone", this.telephone)
231	            .append("email", this.email)
232	            .toString();
233	    }
234	}
