18	import org.slf4j.Logger;
19	import org.slf4j.LoggerFactory;
20	import org.springframework.samples.petclinic.model.Owner;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Emits audit records for owner life-cycle events to the dedicated {@code AUDIT}
25	 * logger, keeping audit side-effects separate from the create business logic.
26	 */
27	@Component
28	public class OwnerAuditor {
29	
30	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
31	
32	    /**
33	     * Record the successful creation of an owner, capturing its id, customer code and
34	     * registration date.
35	     */
36	    public void auditCreated(Owner owner) {
37	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
38	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
39	    }
40	}
