19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "locality", expression = "java(resolveLocality(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
29	    @Mapping(target = "membershipTier", expression = "java(resolveMembershipTier(owner))")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    Owner toOwner(OwnerDto ownerDto);
33	
34	    /**
35	     * Formats the owner's stored names for display as {@code "LastName, FirstName"}.
36	     */
37	    default String formatDisplayName(Owner owner) {
38	        return owner.getLastName() + ", " + owner.getFirstName();
39	    }
40	
41	    /**
42	     * Formats the owner's initials as the upper-cased first letters of firstName and
43	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
44	     */
45	    default String formatInitials(Owner owner) {
46	        return initial(owner.getFirstName()) + initial(owner.getLastName());
47	    }
48	
49	    /** The upper-cased first letter of {@code name} followed by a dot. */
50	    private String initial(String name) {
51	        return Character.toUpperCase(name.charAt(0)) + ".";
52	    }
53	
54	    /**
55	     * Derives the owner's locality (canonical region) from its city via the fixed
56	     * city-to-region table, yielding {@code "UNKNOWN"} for any city not in the table.
57	     */
58	    default String resolveLocality(Owner owner) {
59	        return LocalityResolver.resolve(owner.getCity());
60	    }
61	
62	    /**
63	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
64	     * last two digits of the registration date year, e.g. {@code "LON-SMI-0007-M26"}.
65	     */
66	    default String formatMembershipNumber(Owner owner) {
67	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
68	    }
69	
70	    /**
71	     * Resolves the owner's membership tier: {@code SILVER} when the owner has no namesakes
72	     * (namesakeCount is 0) and an email is present, otherwise {@code BRONZE}.
73	     */
74	    default OwnerDto.MembershipTierEnum resolveMembershipTier(Owner owner) {
75	        boolean noNamesakes = Integer.valueOf(0).equals(owner.getNamesakeCount());
76	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
77	        return noNamesakes && hasEmail ? OwnerDto.MembershipTierEnum.SILVER : OwnerDto.MembershipTierEnum.BRONZE;
78	    }
79	
80	    @Mapping(target = "id", ignore = true)
81	    @Mapping(target = "pets", ignore = true)
82	    @Mapping(target = "householdId", ignore = true)
83	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
84	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
85	    Owner toOwner(OwnerFieldsDto ownerDto);
86	
87	    /**
88	     * Store the address in its canonical form (trimmed, whitespace-collapsed, upper-cased and with
89	     * common abbreviations expanded), so it is always persisted, returned and compared normalized.
90	     */
91	    @Named("normalizeAddress")
92	    default String normalizeAddress(String address) {
93	        return AddressNormalizer.normalize(address);
94	    }
95	
96	    /**
97	     * Store the telephone in E.164 form. Validation ({@code @Telephone}) has already guaranteed
98	     * the raw value normalizes to a valid E.164 number.
99	     */
100	    @Named("normalizeTelephone")
101	    default String normalizeTelephone(String telephone) {
102	        return TelephoneNormalizer.toE164(telephone);
103	    }
104	
105	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
106	
107	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
108	
109	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
110	        OwnerPageDto ownerPageDto = new OwnerPageDto();
111	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
112	        ownerPageDto.setPage(ownerPage.getNumber());
113	        ownerPageDto.setSize(ownerPage.getSize());
114	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
115	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
116	        return ownerPageDto;
117	    }
118	}
